mapper.select:
select h.gym_id as gymId, h.item_category as itemCategory, h.item_name as itemName, sum(h.item_count) as itemCount, (select h2.item_price from "h_item" h2 where h2.gym_id = h.gym_id and h2.item_category = h.item_category and h2.item_name = h.item_name and h2.item_count > 0 order by h2.item_date desc, h2.item_id desc limit 1) as itemPrice, (select h4.item_date from "h_item" h4 where h4.gym_id = h.gym_id and h4.item_category = h.item_category and h4.item_name = h.item_name and h4.item_count > 0 order by h4.item_date desc, h4.item_id desc limit 1) as itemDate, (select min(h3.item_expiry_date) from "h_item" h3 where h3.gym_id = h.gym_id and h3.item_category = h.item_category and h3.item_name = h.item_name and h3.item_count > 0 and h3.item_expiry_date is not null) as itemExpiryDate from "h_item" h where h.gym_id=#{gymId}
order by itemCount desc order by itemCount asc order by itemPrice desc nulls last order by itemPrice asc nulls last order by h.item_name
limit #{pager.pageSize} offset #{pager.offset}

select count(*) from (
    select 1
    from "h_item" h
    where h.gym_id=#{gymId}



) t

select h.gym_id as gymId, h.item_category as itemCategory, h.item_name as itemName, sum(h.item_count) as itemCount from "h_item" h where h.gym_id=#{gymId}
and (h.item_name like concat('%', #{keyword}, '%') or h.item_category like concat('%', #{keyword}, '%'))
order by h.item_name

select * from "h_item"
where gym_id = #{gymId}
  and item_name = #{itemName}
  and item_category = #{itemCategory}
order by item_date desc

mapper.update:
update "h_item"
set item_price=#{itemPrice},item_count=#{itemCount},item_category=#{itemCategory},item_name=#{itemName},item_expiry_date=#{itemExpiryDate, jdbcType=DATE}
where item_id=#{itemId} and gym_id=#{gymId}
